create extension if not exists pgcrypto;
create table if not exists public.ce_decisions(id uuid primary key,diagnosis text not null,recommendation text not null,confidence numeric not null,priority text not null,evidence jsonb not null,engine_version text not null,created_at timestamptz not null default now());
create table if not exists public.ce_missions(id uuid primary key,decision_id uuid not null references public.ce_decisions(id),objective text not null,state text not null,kpi text not null,execution_count integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.ce_events(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.ce_missions(id),decision_id uuid,event_type text not null,from_state text,to_state text,actor_type text not null,metadata jsonb,created_at timestamptz not null default now());
create table if not exists public.ce_action_keys(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.ce_missions(id),action text not null,idempotency_key text not null,created_at timestamptz not null default now(),unique(mission_id,action,idempotency_key));
create table if not exists public.ce_learning(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.ce_missions(id),lesson_type text not null,quality text not null,improved boolean,delta numeric,delta_pct numeric,lesson text not null,reason text not null,created_at timestamptz not null default now());
create table if not exists public.ce_prediction_ledger(id uuid primary key default gen_random_uuid(),decision_id uuid not null references public.ce_decisions(id),mission_id uuid not null references public.ce_missions(id),engine_version text not null,p1r numeric,p2r numeric,p3r numeric,expected_r numeric,risk_gate text,prediction_source text,calibration_status text,outcome_status text not null default 'OPEN',realized_r numeric,outcome_payload jsonb not null default '{}',created_at timestamptz not null default now(),resolved_at timestamptz);
create table if not exists public.ce_program_runs(id uuid primary key,objective text not null,status text not null,version text not null,scope jsonb not null,stages jsonb not null,next_stage integer,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.ce_program_events(id uuid primary key default gen_random_uuid(),program_id uuid not null references public.ce_program_runs(id),event_type text not null,payload jsonb,created_at timestamptz not null default now());
create table if not exists public.ce_program_checkpoints(id uuid primary key,program_id uuid not null references public.ce_program_runs(id),stage_id integer,state text not null,next_stage integer,integrity text not null,created_at timestamptz not null default now());
create index if not exists ce_missions_created_idx on public.ce_missions(created_at desc);create index if not exists ce_events_mission_idx on public.ce_events(mission_id,created_at desc);create index if not exists ce_learning_created_idx on public.ce_learning(created_at desc);create index if not exists ce_predictions_mission_idx on public.ce_prediction_ledger(mission_id,created_at desc);
alter table public.ce_decisions enable row level security;alter table public.ce_missions enable row level security;alter table public.ce_events enable row level security;alter table public.ce_action_keys enable row level security;alter table public.ce_learning enable row level security;alter table public.ce_prediction_ledger enable row level security;alter table public.ce_program_runs enable row level security;alter table public.ce_program_events enable row level security;alter table public.ce_program_checkpoints enable row level security;revoke all on all tables in schema public from anon,authenticated;grant all on all tables in schema public to service_role;
create or replace function public.ce_claim_action(p_mission_id uuid,p_action text,p_idempotency_key text) returns jsonb language plpgsql security definer set search_path=public as $$declare inserted_id uuid;begin insert into ce_action_keys(mission_id,action,idempotency_key)values(p_mission_id,p_action,p_idempotency_key)on conflict do nothing returning id into inserted_id;return jsonb_build_object('claimed',inserted_id is not null,'mission_id',p_mission_id,'action',p_action,'idempotency_key',p_idempotency_key);end;$$;revoke all on function public.ce_claim_action(uuid,text,text) from public,anon,authenticated;grant execute on function public.ce_claim_action(uuid,text,text) to service_role;
